INSERT INTO comunicados (id, created_at, updated_at, activo, contenido, anio_id, autor_id, seccion_id) VALUES
    (1, '2026-03-02 08:00:00', '2026-03-02 08:00:00', true, 'Estimadas familias, damos la bienvenida al año escolar 2026. Las clases inician el 2 de marzo y los horarios ya están disponibles en la plataforma.', 1, 1, NULL),
    (2, '2026-04-06 09:00:00', '2026-04-06 09:00:00', true, 'Se comparte el cronograma de evaluaciones del primer bimestre. Las fechas definitivas serán confirmadas por cada docente en clase.', 1, 2, NULL),
    (3, '2026-05-04 10:00:00', '2026-05-04 10:00:00', true, 'En 3°A reforzaremos operaciones con fracciones y resolución de problemas. Se recomienda revisar los contenidos publicados antes de cada clase.', 1, 3, 3),
    (4, '2026-07-20 08:00:00', '2026-07-20 08:00:00', true, 'Del 27 de julio al 7 de agosto no habrá clases. El retorno a las aulas será el 10 de agosto con el inicio del Bimestre III.', 1, 1, NULL),
    (5, '2026-08-10 09:00:00', '2026-08-10 09:00:00', true, 'Solicitamos a los apoderados actualizar sus teléfonos y correos para garantizar una comunicación oportuna durante el año escolar.', 1, 6, NULL),
    (6, '2026-09-21 10:00:00', '2026-09-21 10:00:00', true, 'En 2°A iniciaremos el proyecto de ecosistemas. Los materiales necesarios se entregarán en clase y el avance se revisará semanalmente.', 1, 8, 2),
    (7, '2026-10-19 08:00:00', '2026-10-19 08:00:00', true, 'Del 19 al 23 de octubre celebramos la Semana de la Familia con actividades culturales y deportivas. La asistencia de las familias es importante.', 1, 1, NULL),
    (8, '2026-11-16 09:00:00', '2026-11-16 09:00:00', true, 'Las boletas del Bimestre IV estarán disponibles en la plataforma a partir del 16 de noviembre. Las consultas se atienden en Secretaría.', 1, 2, NULL);
